items := make([]ChargeItem, 0, len(o.Lines))
var sum int64
for _, l := range o.Lines {
	items = append(items, ChargeItem{Name: l.Name, Quantity: l.Quantity, Amount: l.Price})
	sum += int64(l.Quantity) * l.Price
}
// The lines must add up to what the order says; a coupon is one negative line.
if o.Discount > 0 {
	items = append(items, ChargeItem{Name: "Discount", Quantity: 1, Amount: -o.Discount})
	sum -= o.Discount
}
if sum != o.Total {
	return nil, fmt.Errorf("order %s: lines add up to %d, total is %d", o.ID, sum, o.Total)
}
